style.css:
::-webkit-scrollbar {
  width: 4px;
  border-radius: 10px;
  transition: all 0.4s ease;
  height: 4px;
}

::-webkit-scrollbar-track {
  background: #b5b5b56c;
  border-radius: 10px;
  transition: all 0.4s ease;
}

::-webkit-scrollbar-thumb {
  background: #2c7385;
  border-radius: 10px;
  transition: all 0.4s ease;
}

::-webkit-scrollbar-thumb:hover {
  background: #0386b5;
  transition: all 0.4s ease;
  cursor: pointer;
  border-radius: 0px;
}
